import { Center } from "@react-three/drei";
import { useLoader } from "@react-three/fiber";
import { useEffect, useMemo } from "react";
import { Box3, Vector3 } from "three";
import { MeshoptDecoder } from "three/addons/libs/meshopt_decoder.module.js";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";

// Generated by `npm run optimize:model` from assets/models/apex-helmet.source.glb.
export const HELMET_URL = "/models/apex-helmet.glb";

// The optimized GLB uses meshopt geometry compression. The decoder ships
// inside three.js, so there's no extra download or CDN request.
function withMeshopt(loader: GLTFLoader) {
  loader.setMeshoptDecoder(MeshoptDecoder);
}

// World-space height the helmet is normalized to. HelmetCanvas frames its
// camera around this, so the model file's own units don't matter.
export const HELMET_HEIGHT = 2;

// Y rotation (radians) that turns the visor toward the camera.
const FACING_Y = 0;

type HelmetModelProps = {
  onProgress?: (event: ProgressEvent) => void;
  onLoaded?: () => void;
};

export default function HelmetModel({ onProgress, onLoaded }: HelmetModelProps) {
  // Suspends until the file is parsed, then caches it by URL. We call R3F's
  // useLoader directly (Drei's useGLTF wraps it) because only useLoader
  // exposes download progress for the loading fallback.
  const { scene } = useLoader(GLTFLoader, HELMET_URL, withMeshopt, onProgress);

  const scale = useMemo(() => {
    const size = new Box3().setFromObject(scene).getSize(new Vector3());
    return HELMET_HEIGHT / size.y;
  }, [scene]);

  useEffect(() => {
    onLoaded?.();
  }, [onLoaded]);

  // The scene is rendered as-is: no material or texture overrides.
  // dispose={null} keeps the cached model intact when the page unmounts.
  return (
    <group scale={scale}>
      <Center>
        <primitive object={scene} rotation-y={FACING_Y} dispose={null} />
      </Center>
    </group>
  );
}
